const SAFE_BASE_ENV_NAMES = new Set<string>([
  'PATH',
  'HOME',
  'SHELL',
  'TERM',
  'LANG',
  'LANGUAGE',
  'TMPDIR',
  'TMP',
  'TEMP',
  'USER',
  'LOGNAME',
  'PWD',
  'COLUMNS',
  'LINES',
  'TZ',
]);

